HOURLY_BLINK = True
BLINK_RGB_PIN = 48
BLINK_COLOR = (0, 90, 200)   # 蓝色; 改成 (200, 0, 0) 即红色
BLINK_TIMES = 3              # 闪 3 下
BLINK_ON_MS = 140
BLINK_OFF_MS = 160

_rgb = None
if HOURLY_BLINK:
    try:
        import neopixel
        _rgb = neopixel.NeoPixel(machine.Pin(BLINK_RGB_PIN), 1)
        _rgb[0] = (0, 0, 0)
        _rgb.write()
    except Exception as e:
        print("[rgb] unavailable:", e)
        HOURLY_BLINK = False


def rgb_blink():
    if not _rgb:
        return
    print("[rgb] hourly blink")
    for _ in range(BLINK_TIMES):
        _rgb[0] = BLINK_COLOR
        _rgb.write()
        time.sleep_ms(BLINK_ON_MS)
        _rgb[0] = (0, 0, 0)
        _rgb.write()
        if _ != BLINK_TIMES - 1:
            time.sleep_ms(BLINK_OFF_MS)


