# ================= EPD 驱动 =================
busy = machine.Pin(7, machine.Pin.IN, machine.Pin.PULL_UP)
rst = machine.Pin(8, machine.Pin.OUT, value=1)
dc = machine.Pin(9, machine.Pin.OUT, value=1)
cs = machine.Pin(10, machine.Pin.OUT, value=1)
spi = machine.SoftSPI(baudrate=2000000, polarity=0, phase=0,
                      sck=machine.Pin(12), mosi=machine.Pin(11), miso=machine.Pin(6))


def wait_busy(ms=60000):
    t = time.ticks_ms()
    while busy.value():
        if time.ticks_diff(time.ticks_ms(), t) > ms:
            raise RuntimeError("BUSY timeout")
        time.sleep_ms(5)


def cmd(c, data=None):
    dc.value(0)
    cs.value(0)
    spi.write(bytes((c,)))
    if data is not None:
        dc.value(1)
        spi.write(data)
    cs.value(1)
    dc.value(1)


def reset():
    rst.value(0)
    time.sleep_ms(10)
    rst.value(1)
    time.sleep_ms(10)
    wait_busy()


def init():
    reset()
    cmd(0x01, b"\x8f\x01\x00")
    cmd(0x21, b"\x00\x00")
    cmd(0x3C, b"\x05")
    cmd(0x11, b"\x03")
    cmd(0x18, b"\x80")
    cmd(0x22, b"\xf7")
    time.sleep_ms(50)


def window():
    cmd(0x44, b"\x00\x31")
    cmd(0x45, b"\x00\x00\x2b\x01")
    cmd(0x4E, b"\x00")
    cmd(0x4F, b"\x00\x00")


def refresh():
    cmd(0x20)
    wait_busy()
    cmd(0x02)
    wait_busy()
    cmd(0x07, b"\x03")


def conv_bw(fb):
    for i in range(N):
        fb[i] ^= 0xFF
    return fb


def conv_red(fr):
    return fr


# ================= 画布(位1=黑墨/红墨; 'w'=在黑底上挖白) =================
class Canvas:
    def __init__(self):
        self.fb = bytearray(N)
        self.fr = bytearray(N)

    def _set(self, buf, x, y):
        if 0 <= x < W and 0 <= y < H:
            buf[y * RB + (x >> 3)] |= 0x80 >> (x & 7)

    def _clr(self, x, y):
        if 0 <= x < W and 0 <= y < H:
            i = y * RB + (x >> 3)
            m = (0x80 >> (x & 7)) ^ 0xFF
            self.fb[i] &= m
            self.fr[i] &= m

    def text(self, font, s, x, y, color="k"):
        cx = x
        for ch in s:
            g = font.get(ch)
            if g is None:
                cx += 8
                continue
            w, h, dy, data = g[0], g[1], g[2], g[3:]
            bw = (w + 7) >> 3
            if color == "w":
                for ry in range(h):
                    row = y + dy + ry
                    if row < 0 or row >= H:
                        continue
                    for xb in range(w):
                        if data[ry * bw + (xb >> 3)] & (0x80 >> (xb & 7)):
                            self._clr(cx + xb, row)
            else:
                buf = self.fr if color == "r" else self.fb
                for ry in range(h):
                    row = y + dy + ry
                    if row < 0 or row >= H:
                        continue
                    base = row * RB
                    for xb2 in range(bw):
                        v = data[ry * bw + xb2]
                        if not v:
                            continue
                        px = cx + xb2 * 8
                        bi = px >> 3
                        sh = px & 7
                        if bi < RB:
                            buf[base + bi] |= v >> sh
                        if sh and bi + 1 < RB:
                            buf[base + bi + 1] |= (v << (8 - sh)) & 0xFF
            cx += w

    def rect(self, x0, y0, x1, y1, color="k"):
        for y in range(int(y0), int(y1) + 1):
            for x in range(int(x0), int(x1) + 1):
                if color == "w":
                    self._clr(x, y)
                else:
                    self._set(self.fr if color == "r" else self.fb, x, y)

    def hline(self, x0, x1, y, color="k", w=2, dash=0):
        for t in range(w):
            for x in range(int(x0), int(x1) + 1):
                if not dash or (x // dash) % 2 == 0:
                    self._set(self.fr if color == "r" else self.fb, x, y + t)

    def vline(self, x, y0, y1, color="k", w=1, dash=0):
        for t in range(w):
            for y in range(int(y0), int(y1) + 1):
                if not dash or (y // dash) % 2 == 0:
                    self._set(self.fr if color == "r" else self.fb, x + t, y)


